toolScript:
// --- PRO AUDIO LOGIC ---
        let audioCtx, analyser, dataArray, stream;
        let isTesting = false;
        let startTime = 0;
        let canvas, ctx;
        // Features: Rolling Average
        let historyQueue = [];
        function initAudio() {
            if (audioCtx) return;
            audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            analyser = audioCtx.createAnalyser();
            analyser.fftSize = 2048;
            dataArray = new Uint8Array(analyser.frequencyBinCount);
            canvas = document.getElementById('visualizer');
            ctx = canvas.getContext('2d');
            resizeCanvas();
            draw();
        }
        function resizeCanvas() {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
        }
        async function startTest() {
            initAudio();
            const btn = document.getElementById('start-btn');
            const status = document.getElementById('status-text');
            if (isTesting) return;
            isTesting = true;
            btn.disabled = true;
            btn.classList.add('opacity-50');
            status.innerText = "Analyzing Ambient Noise Floor...";
            try {
                if (!stream) {
                    stream = await navigator.mediaDevices.getUserMedia({
                        audio: {
                            echoCancellation: false,
                            noiseSuppression: false,
                            autoGainControl: false
                        }
                    });
                    const micSource = audioCtx.createMediaStreamSource(stream);
                    micSource.connect(analyser);
                }
                // Clear UI for next read
                document.getElementById('latency-val').innerText = "-- ms";
                document.getElementById('raw-val').innerText = "-- ms";
                document.getElementById('air-val').innerText = "- 0.0 ms";
                // Slight delay to ensure buffer is clear
                setTimeout(() => {
                    status.innerText = "Broadcasting Acoustic Pulse...";
                    playPulse();
                }, 400);
            } catch (err) {
                console.error(err);
                alert("Microphone access denied. Loopback required for measurement.");
                isTesting = false;
                btn.disabled = false;
                btn.classList.remove('opacity-50');
            }
        }
        function playPulse() {
            const freq = parseFloat(document.getElementById('ping-freq').value) || 1000;
            const osc = audioCtx.createOscillator();
            const g = audioCtx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
            // Envelope for a sharp, non-popping click
            g.gain.setValueAtTime(0, audioCtx.currentTime);
            g.gain.linearRampToValueAtTime(1, audioCtx.currentTime + 0.001);
            g.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.015);
            osc.connect(g);
            g.connect(audioCtx.destination);
            startTime = performance.now();
            osc.start();
            osc.stop(audioCtx.currentTime + 0.02);
            detectReturn();
        }
        function detectReturn() {
            const threshold = parseFloat(document.getElementById('threshold').value) * 255;
            const status = document.getElementById('status-text');
            function check() {
                analyser.getByteFrequencyData(dataArray);
                let max = 0;
                for (let i = 0; i < dataArray.length; i++) {
                    if (dataArray[i] > max) max = dataArray[i];
                }
                if (max > threshold) {
                    const endTime = performance.now();
                    const rawLatency = endTime - startTime;
                    // --- DISTANCE MATH ---
                    const distanceCm = parseFloat(document.getElementById('distance-cm').value) || 0;
                    // speed of sound = 343 m/s = 34300 cm/s
                    // time (s) = distance / speed
                    const airDelayMs = (distanceCm / 100) / 343 * 1000;
                    let trueLatency = rawLatency - airDelayMs;
                    if (trueLatency < 0) trueLatency = 0.1; // Clamp sanity check
                    // Update UI
                    document.getElementById('raw-val').innerText = rawLatency.toFixed(1) + " ms";
                    document.getElementById('air-val').innerText = "- " + airDelayMs.toFixed(1) + " ms";
                    document.getElementById('latency-val').innerText = trueLatency.toFixed(1) + " ms";
                    // Rolling Average Logic
                    historyQueue.push(trueLatency);
                    if (historyQueue.length > 5) {
                        historyQueue.shift(); // keep only last 5
                    }
                    const avg = historyQueue.reduce((a, b) => a + b, 0) / historyQueue.length;
                    document.getElementById('avg-val').innerText = `5-Ping Avg: ${avg.toFixed(1)} ms`;
                    status.innerText = "Loopback Signal Captured Successfully";
                    finishTest();
                } else if (performance.now() - startTime > 2000) {
                    document.getElementById('latency-val').innerText = "FAIL";
                    status.innerText = "Signal Lost: Move mic closer or turn up volume.";
                    finishTest();
                } else {
                    requestAnimationFrame(check);
                }
            }
            check();
        }
        function finishTest() {
            isTesting = false;
            const btn = document.getElementById('start-btn');
            btn.disabled = false;
            btn.classList.remove('opacity-50');
            btn.innerText = "Fire Acoustic Pulse";
        }
        function resetStats() {
            historyQueue = [];
            document.getElementById('latency-val').innerText = "-- ms";
            document.getElementById('raw-val').innerText = "-- ms";
            document.getElementById('air-val').innerText = "- 0.0 ms";
            document.getElementById('avg-val').innerText = "5-Ping Avg: -- ms";
            document.getElementById('status-text').innerText = "History Cleared. Awaiting Signal Calibration.";
        }
        function draw() {
            requestAnimationFrame(draw);
            if (!analyser) return;
            analyser.getByteTimeDomainData(dataArray);
            ctx.fillStyle = '#0f172a'; // Background
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.lineWidth = 2;
            ctx.strokeStyle = '#3b82f6';
            ctx.beginPath();
            const sliceWidth = canvas.width * 1.0 / dataArray.length;
            let x = 0;
            for (let i = 0; i < dataArray.length; i++) {
                const v = dataArray[i] / 128.0;
                const y = v * canvas.height / 2;
                if (i === 0) ctx.moveTo(x, y);
                else ctx.lineTo(x, y);
                x += sliceWidth;
            }
            ctx.lineTo(canvas.width, canvas.height / 2);
            ctx.stroke();
        }
        window.addEventListener('resize', resizeCanvas);
